export default function UsersPage() {
  const [users, setUsers] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [editUserId, setEditUserId] = useState(null);
  const [userToDelete, setUserToDelete] = useState(null);
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    phone: "",
    role: "HEAD",
    department: "Micro",
    branch: "Main Branch",
    password: "",
  });
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [usersLoading, setUsersLoading] = useState(
    () => !isCached(CACHE_KEYS.USERS),
  );

  const fetchUsers = async () => {
    try {
      await fetchWithCache(`${API_URL}/api/users`, CACHE_KEYS.USERS, (data) =>
        setUsers(
          data.filter((u) => u.role !== "ADMIN" && u.role !== "ADMIN_OFFICER"),
        ),
      );
    } catch (err) {
      console.error(err);
    } finally {
      setUsersLoading(false);
    }
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const handleNameChange = (e) => {
    const newName = e.target.value;
    const firstName = newName
      .split(" ")[0]
      .toLowerCase()
      .replace(/[^a-z0-9]/g, "");
    setFormData((prev) => ({
      ...prev,
      name: newName,
      password: editUserId ? prev.password : firstName ? `${firstName}123` : "",
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setSuccess("");

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const phoneRegex = /^\+?[\d\s-]{10,15}$/;

    if (!emailRegex.test(formData.email)) {
      setError("Please enter a valid email address.");
      return;
    }
    if (!phoneRegex.test(formData.phone)) {
      setError("Please enter a valid phone number (10-15 digits).");
      return;
    }
    try {
      if (editUserId) {
        await axios.put(`${API_URL}/api/users/${editUserId}`, formData);
        setSuccess("User updated successfully.");
      } else {
        const res = await axios.post(`${API_URL}/api/users`, formData);
        setSuccess(
          `User created successfully. Temporary password is: ${res.data.temporaryPassword}`,
        );
      }
      setFormData({
        name: "",
        email: "",
        phone: "",
        role: "HEAD",
        department: "Micro",
        branch: "Main Branch",
        password: "",
      });
      setEditUserId(null);
      setShowForm(false);
      invalidateCache(CACHE_KEYS.USERS);
      fetchUsers();
    } catch (err) {
      setError(err.response?.data?.message || "Operation failed");
    }
  };

  const handleEdit = (u) => {
    setFormData({
      name: u.name,
      email: u.email,
      phone: u.phone,
      role: u.role,
      department: u.department,
      branch: u.branch,
      password: "",
    });
    setEditUserId(u._id);
    setShowForm(true);
    setError("");
    setSuccess("");
  };

  const confirmDelete = async (id) => {
    try {
      await axios.delete(`${API_URL}/api/users/${id}`);
      invalidateCache(CACHE_KEYS.USERS);
      fetchUsers();
    } catch (err) {
      console.error(err);
      setError("Failed to delete user");
    }
  };

  const headUsers = users.filter((u) => u.role === "HEAD");
  const assistantUsers = users.filter((u) => u.role === "ASSISTANT");

  return (
    <div>
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: "1.5rem",
          flexWrap: "wrap",
          gap: "0.75rem",
        }}
      >
        <h1>User Management</h1>
        <button
          className="btn btn-primary"
          onClick={() => {
            setShowForm(!showForm);
            if (showForm) setEditUserId(null);
          }}
        >
          {showForm ? "Close Form" : "+ Create User"}
        </button>
      </div>

      {error && (
        <div
          style={{
            marginBottom: "1rem",
            color: "var(--color-danger)",
            backgroundColor: "var(--color-danger-light)",
            padding: "1rem",
            borderRadius: "var(--radius-md)",
          }}
        >
          {error}
        </div>
      )}
      {success && (
        <div
          style={{
            position: "fixed",
            top: "6rem",
            right: "2rem",
            zIndex: 1000,
            color: "white",
            backgroundColor: "var(--color-success)",
            padding: "1rem 1.5rem",
            borderRadius: "var(--radius-md)",
            boxShadow: "0 4px 12px rgba(0,0,0,0.15)",
            display: "flex",
            alignItems: "center",
            gap: "0.75rem",
            animation: "slideIn 0.3s ease-out",
          }}
        >
          <CheckCircle size={20} />
          <span style={{ fontWeight: 500 }}>{success}</span>
        </div>
      )}

      {showForm && (
        <div className="card" style={{ marginBottom: "2.5rem" }}>
          <h3 style={{ marginBottom: "1rem" }}>
            {editUserId ? "Edit User" : "Create User"}
          </h3>
          <form
            onSubmit={handleSubmit}
            style={{ display: "flex", flexDirection: "column", gap: "1rem" }}
          >
            <div className="flex-row-responsive">
              <div style={{ flex: 1 }}>
                <label
                  style={{
                    display: "block",
                    fontSize: "0.9rem",
                    marginBottom: "0.4rem",
                    fontWeight: 500,
                  }}
                >
                  Full Name
                </label>
                <input
                  type="text"
                  value={formData.name}
                  onChange={handleNameChange}
                  required
                />
              </div>
              <div style={{ flex: 1 }}>
                <label
                  style={{
                    display: "block",
                    fontSize: "0.9rem",
                    marginBottom: "0.4rem",
                    fontWeight: 500,
                  }}
                >
                  Email Address
                </label>
                <input
                  type="email"
                  value={formData.email}
                  onChange={(e) =>
                    setFormData({ ...formData, email: e.target.value })
                  }
                  required
                />
              </div>
            </div>
            <div className="flex-row-responsive">
              <div style={{ flex: 1 }}>
                <label
                  style={{
                    display: "block",
                    fontSize: "0.9rem",
                    marginBottom: "0.4rem",
                    fontWeight: 500,
                  }}
                >
                  Phone Number
                </label>
                <input
                  type="text"
                  value={formData.phone}
                  onChange={(e) =>
                    setFormData({ ...formData, phone: e.target.value })
                  }
                  required
                />
              </div>
              <div style={{ flex: 1 }}>
                <label
                  style={{
                    display: "block",
                    fontSize: "0.9rem",
                    marginBottom: "0.4rem",
                    fontWeight: 500,
                  }}
                >
                  Role
                </label>
                <select
                  value={formData.role}
                  onChange={(e) =>
                    setFormData({ ...formData, role: e.target.value })
                  }
                  required
                >
                  <option value="HEAD">Department Head</option>
                  <option value="ASSISTANT">Lab Assistant</option>
                </select>
              </div>
              <div style={{ flex: 1 }}>
                <label
                  style={{
                    display: "block",
                    fontSize: "0.9rem",
                    marginBottom: "0.4rem",
                    fontWeight: 500,
                  }}
                >
                  Department
                </label>
                <select
                  value={formData.department}
                  onChange={(e) =>
                    setFormData({ ...formData, department: e.target.value })
                  }
                  required
                >
                  <option value="Micro">Micro</option>
                  <option value="Chemical">Chemical</option>
                </select>
              </div>
            </div>
            {!editUserId && (
              <div className="flex-row-responsive">
                <div style={{ flex: 1 }}>
                  <label
                    style={{
                      display: "block",
                      fontSize: "0.9rem",
                      marginBottom: "0.4rem",
                      fontWeight: 500,
                    }}
                  >
                    Password (Auto-generated)
                  </label>
                  <input
                    type="text"
                    value={formData.password}
                    onChange={(e) =>
                      setFormData({ ...formData, password: e.target.value })
                    }
                    required
                  />
                </div>
              </div>
            )}
            <div>
              <button
                type="submit"
                className="btn btn-primary"
                style={{ marginTop: "0.5rem" }}
              >
                {editUserId ? "Update User" : "Submit & Create"}
              </button>
            </div>
          </form>
        </div>
      )}

      <UserSection
        title="Department Heads"
        users={headUsers}
        isLoading={usersLoading}
        onEdit={handleEdit}
        onConfirmDelete={confirmDelete}
        userToDelete={userToDelete}
        setUserToDelete={setUserToDelete}
      />

      <UserSection
        title="Lab Assistants"
        users={assistantUsers}
        isLoading={usersLoading}
        onEdit={handleEdit}
        onConfirmDelete={confirmDelete}
        userToDelete={userToDelete}
        setUserToDelete={setUserToDelete}
      />
    </div>
  );
}

import React from "react";
import { Routes, Route, useLocation, useNavigate } from "react-router-dom";
import DataSettings from "./DataSettings";
import ActivityLogsPage from './ActivityLogsPage';

import Dashboard from "./AdminOfficer/AdminOfficerStats";
import Jobs from "./AdminOfficer/JobsPage";
import UsersPage from "./AdminOfficer/UsersPage";
import API_URL from "../utils/api";

function Audit() {
  const navigate = useNavigate();
  return (
    <ActivityLogsPage
      title="Global Job Logs & Reports"
      fetchUrl={`${API_URL}/api/jobs`}
      enableSocketUpdates={true}
      onReopen={(job) => navigate("/admin-officer/jobs", { state: { reopenJob: job } })}
    />
  );
}

export default function AdminOfficerDashboard() {
  return (
    <Routes>
      <Route path="/" element={<Dashboard />} />
      <Route path="/jobs" element={<Jobs />} />

      <Route path="/audit" element={<Audit />} />
      <Route path="/users" element={<UsersPage />} />
      <Route path="/data-settings" element={<DataSettings />} />
      <Route path="/settings" element={<div>System Settings Page</div>} />
    </Routes>
  );
}

