                      </div>
                      <div style={{ fontSize: "0.8rem", marginTop: "0.15rem" }}>
                        <span
                          style={{
                            fontWeight: 600,
                            color: "var(--color-primary)",
                          }}
                        >
                          {deptParams.length}
                        </span>
                        <span style={{ color: "var(--color-text-muted)" }}>
                          {" "}
                          parameter{deptParams.length !== 1 ? "s" : ""}
                        </span>
                      </div>
                    </div>
                    {isExpanded ? (
                      <ChevronDown size={20} color="var(--color-primary)" />
                    ) : (
                      <ChevronRight size={20} color="var(--color-text-muted)" />
                    )}
                  </div>
                </div>

                {/* Expanded Dispatch Form */}
                {isExpanded && (
                  <div
                    style={{
                      padding: "1.5rem",
                      borderTop: "1px solid var(--color-border)",
                      backgroundColor: "var(--color-surface)",
                    }}
                  >
                    {deptParams.length === 0 ? (
                      <p
                        style={{
                          color: "var(--color-text-muted)",
                          textAlign: "center",
                          padding: "1rem",
                        }}
                      >
                        No parameters for your department in this job.
                      </p>
                    ) : (
                      (() => {
                        const dept = user?.department
                          ? user.department.toLowerCase()
                          : "";
                        const dKey = dept === "chemical" ? "chemical" : dept;
                        const otherKey =
                          dKey === "chemical" ? "micro" : "chemical";
                        const distStatus = job.distribution[dKey].status;
                        const isMultiDept =
                          job.distribution.micro.required &&
                          job.distribution.chemical.required;

                        const isReviewing = distStatus === "PENDING_REVIEW";
                        const isApproved = distStatus === "REVIEW_APPROVED";
                        const isPending = distStatus === "PENDING";

                        return (
                          <>
                            {/* Parameter rows (Always visible) */}
                            <div
                              style={{
                                display: "flex",
                                flexDirection: "column",
                                gap: "0.5rem",
                                marginBottom: "1.5rem",
                              }}
                            >
                              {deptParams.map((p) => (
                                <div
                                  key={p.parameterId._id}
                                  style={{
                                    display: "flex",
                                    justifyContent: "space-between",
                                    alignItems: "center",
                                    backgroundColor:
                                      "var(--color-surface-hover)",
                                    padding: "0.6rem 1rem",
                                    borderRadius: "var(--radius-md)",
                                    gap: "1rem",
                                  }}
                                >
                                  <div style={{ flex: 1 }}>
                                    <span style={{ fontWeight: 600 }}>
                                      {p.name}
                                    </span>{" "}
                                    <span
                                      style={{
                                        fontSize: "0.8rem",
                                        color: "var(--color-text-muted)",
                                      }}
                                    >
                                      ({p.unit})
                                    </span>
                                  </div>

                                  {isPending && (
                                    <select
                                      value={
                                        assignments[
                                        `${job._id}-${p.parameterId._id}`
                                        ] || ""
                                      }
                                      onChange={(e) =>
                                        handleAssign(
                                          job._id,
                                          p.parameterId._id,
                                          e.target.value,
                                        )
                                      }
                                      required
                                      disabled={
                                        iAmChemical && !canChemicalDispatch
                                      }
                                      style={{
                                        minWidth: "180px",
                                        opacity:
                                          iAmChemical && !canChemicalDispatch
                                            ? 0.6
                                            : 1,
                                      }}
                                    >
                                      <option value="" disabled>
                                        Select Analyst...
                                      </option>
                                      {assistants.map((ast) => (
                                        <option key={ast._id} value={ast._id}>
                                          {ast.name}
                                        </option>
                                      ))}
                                    </select>
                                  )}
                                </div>
                              ))}
                            </div>

                            {/* Action Blocks based on Status */}
                            {isReviewing && (
                              <div
                                style={{
                                  textAlign: "center",
                                  padding: "1.5rem",
                                  borderTop: "1px solid var(--color-border)",
                                }}
                              >
                                <h3
                                  style={{
                                    color: "var(--color-warning)",
                                    marginBottom: "0.5rem",
                                    fontSize: "1.2rem",
                                  }}
                                >
                                  Approval Required
                                </h3>
                                <p
                                  style={{
                                    color: "var(--color-text-muted)",
                                    fontSize: "0.9rem",
                                    marginBottom: "1.5rem",
                                  }}
                                >
                                  Please review the job details and parameters
                                  above before approving. You must approve the
                                  job before analysts can be assigned.
                                </p>
                                <div
                                  style={{
                                    display: "flex",
                                    gap: "1rem",
                                    justifyContent: "center",
                                  }}
                                >
                                  <button
                                    onClick={async () => {
                                      try {
                                        await axios.put(
                                          `${API_URL}/api/jobs/${job._id}/approve-review`,
                                          {},
                                          {
                                            headers: {
                                              Authorization: `Bearer ${localStorage.getItem("token")}`,
                                            },
                                          },
                                        );
                                        invalidateCache(CACHE_KEYS.JOBS_HEAD_ACTIVE);
                                        fetchJobs();
                                      } catch (err) {
                                        alert(
                                          err.response?.data?.message ||
                                          "Error approving job",
                                        );
                                      }
                                    }}
                                    className="btn btn-success"
                                    style={{
                                      padding: "0.6rem 1.5rem",
                                      display: "flex",
                                      alignItems: "center",
                                      gap: "0.5rem",
                                    }}
                                  >
                                    <ClipboardCheck size={18} /> Approve Job
                                  </button>
                                  <button
                                    onClick={() => {
                                      setReturnModalData({
                                        jobId: job._id,
                                        dept: dKey,
                                      });
                                      setReturnNote("");
                                    }}
                                    className="btn btn-secondary"
                                    style={{
                                      padding: "0.6rem 1.5rem",
                                      display: "flex",
                                      alignItems: "center",
                                      gap: "0.5rem",
                                      color: "#B45309",
                                      border: "1px solid #F59E0B",
                                      backgroundColor: "#FFFBEB",
                                    }}
                                  >
                                    <RotateCcw size={18} /> Return Job
                                  </button>
                                </div>
                              </div>
                            )}

                            {isApproved && (
                              <div
                                style={{
                                  textAlign: "center",
                                  padding: "1.5rem",
                                  borderTop: "1px solid var(--color-border)",
                                }}
                              >
                                <h3
                                  style={{
                                    color: "var(--color-success)",
                                    marginBottom: "0.5rem",
                                    fontSize: "1.2rem",
                                  }}
                                >
                                  Approved by{" "}
                                  {dKey === "micro" ? "Micro" : "Chemical"}
                                </h3>
                                <p
                                  style={{
                                    color: "var(--color-text-muted)",
                                    fontSize: "0.9rem",
                                    marginBottom: "1.5rem",
                                  }}
                                >
                                  Waiting for the{" "}
                                  {otherKey === "micro" ? "Micro" : "Chemical"}{" "}
                                  department to approve their details before the
                                  job unlocks.
                                </p>
                                <button
                                  onClick={() => {
                                    setReturnModalData({
                                      jobId: job._id,
                                      dept: dKey,
                                    });
                                    setReturnNote("");
                                  }}
                                  className="btn btn-secondary"
                                  style={{
                                    padding: "0.6rem 1.5rem",
                                    display: "flex",
                                    alignItems: "center",
                                    gap: "0.5rem",
                                    color: "#B45309",
                                    border: "1px solid #F59E0B",
                                    backgroundColor: "#FFFBEB",
                                    margin: "0 auto",
                                  }}
                                >
                                  <RotateCcw size={18} /> Return Job
                                </button>
                              </div>
                            )}

                            {isPending && (
                              <>
                                {iAmChemical && !canChemicalDispatch ? (
                                  (() => {
                                    // Determine if this job is the non-anchor sibling (should redirect to sibling for transfer)
                                    const siblingIsMultiDept =
                                      job.siblingJobId &&
                                      job.siblingJobId.distribution?.micro
                                        ?.required &&
                                      job.siblingJobId.distribution?.chemical
                                        ?.required;
                                    const isNonAnchor =
                                      job.sample?.nabl_type === "Non Nabl" &&
                                      siblingIsMultiDept;

                                    return (
                                      <div
                                        style={{
                                          textAlign: "center",
                                          padding: "1.5rem",
                                          borderTop:
                                            "1px solid var(--color-border)",
                                          backgroundColor:
                                            "var(--color-surface-hover)",
                                        }}
                                      >
                                        <h3
                                          style={{
                                            color: "var(--color-warning)",
                                            marginBottom: "0.5rem",
                                            fontSize: "1.1rem",
                                            display: "flex",
                                            alignItems: "center",
                                            justifyContent: "center",
                                            gap: "0.5rem",
                                          }}
                                        >
                                          <Lock size={18} /> Dispatch Locked
                                        </h3>
                                        {transferState ===
                                          "PENDING_APPROVAL" && (
                                            <p
                                              style={{
                                                color: "var(--color-text-muted)",
                                                fontSize: "0.9rem",
                                                marginBottom: 0,
                                              }}
                                            >
                                              Waiting for sibling job to be
                                              approved before transfer can begin.
                                            </p>
                                          )}
                                        {transferState ===
                                          "PENDING_TRANSFER" && (
                                            <p
                                              style={{
                                                color: "var(--color-text-muted)",
                                                fontSize: "0.9rem",
                                                marginBottom: 0,
                                              }}
                                            >
                                              {isNonAnchor
                                                ? `Please accept the sample transfer in the NABL sibling job (${job.siblingJobId?.jobCode || "sibling"}) first.`
                                                : "Waiting for Micro department to transfer the sample."}
                                            </p>
                                          )}
                                        {transferState === "IN_TRANSIT" && (
                                          <p
                                            style={{
                                              color: "var(--color-text-muted)",
                                              fontSize: "0.9rem",
                                              marginBottom: 0,
                                            }}
                                          >
                                            {isNonAnchor
                                              ? `Please accept the sample transfer in the NABL sibling job (${job.siblingJobId?.jobCode || "sibling"}) first.`
                                              : "Sample is in transit. Please confirm receipt from your dashboard above."}
                                          </p>
                                        )}
                                      </div>
                                    );
                                  })()
                                ) : (
                                  <>
                                    {/* Bulk assign */}
                                    <div
                                      style={{
                                        display: "flex",
                                        justifyContent: "space-between",
                                        alignItems: "center",
                                        marginBottom: "1rem",
                                        borderTop:
                                          "1px solid var(--color-border)",
                                        paddingTop: "1.5rem",
                                      }}
                                    >
                                      <div></div>
                                      <div
                                        style={{
                                          display: "flex",
                                          alignItems: "center",
                                          gap: "0.5rem",
                                        }}
                                      >
                                        <label
                                          style={{
                                            fontSize: "0.85rem",
                                            color: "var(--color-text-muted)",
                                          }}
                                        >
                                          Bulk assign all to:
                                        </label>
                                        <select
                                          onChange={(e) => {
                                            handleAssignAll(
                                              job._id,
                                              e.target.value,
                                              deptParams,
                                            );
                                            e.target.value = "";
                                          }}
                                          defaultValue=""
                                          style={{ minWidth: "150px" }}
                                        >
                                          <option value="" disabled>
                                            Select analyst...
                                          </option>
                                          {assistants.map((ast) => (
                                            <option
                                              key={ast._id}
                                              value={ast._id}
                                            >
                                              {ast.name}
                                            </option>
                                          ))}
                                        </select>
                                      </div>
                                    </div>

                                    {/* Deadline + Submit */}
