                                        >
                                          Deadline Date{" "}
                                          <span
                                            style={{
                                              color: "var(--color-danger)",
                                            }}
                                          >
                                            *
                                          </span>
                                        </label>
                                        <input
                                          type="date"
                                          value={deadlineDates[job._id] || ""}
                                          onChange={(e) => {
                                            setDeadlineDates((prev) => ({
                                              ...prev,
                                              [job._id]: e.target.value,
                                            }));
                                            setDeadlineTimes((prev) => {
                                              if (
                                                !prev[job._id] &&
                                                e.target.value
                                              ) {
                                                return {
                                                  ...prev,
                                                  [job._id]: "17:00",
                                                };
                                              }
                                              return prev;
                                            });
                                          }}
                                          required
                                          style={{ width: "100%" }}
                                        />
                                      </div>
                                      <div style={{ flex: "1 1 130px" }}>
                                        <label
                                          style={{
                                            display: "block",
                                            fontSize: "0.82rem",
                                            marginBottom: "0.4rem",
                                            fontWeight: 500,
                                            color: "var(--color-text-muted)",
                                          }}
                                        >
                                          Due Time{" "}
                                          <span
                                            style={{
                                              color: "var(--color-danger)",
                                            }}
                                          >
                                            *
                                          </span>
                                        </label>
                                        <input
                                          type="time"
                                          value={deadlineTimes[job._id] || ""}
                                          onChange={(e) =>
                                            setDeadlineTimes((prev) => ({
                                              ...prev,
                                              [job._id]: e.target.value,
                                            }))
                                          }
                                          required
                                          style={{ width: "100%" }}
                                        />
                                      </div>
                                      <div
                                        style={{
                                          flex: "0 0 auto",
                                          display: "flex",
                                          gap: "0.5rem",
                                        }}
                                      >
                                        <button
                                          type="button"
