                    <Spinner size="sm" color="#fff" />
                  ) : (
                    "Return Job"
                  )}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {detailsJob && (
        <JobDetailsModal job={detailsJob} onClose={() => setDetailsJob(null)} />
      )}

      <InfiniteScroll hasMore={hasMoreJobs} isLoading={isLoadingMore} onLoadMore={loadMoreJobs} />
    </div>
  );
}

import React, { useState, useEffect, useContext } from "react";
import axios from "axios";
import { useLocation, useNavigate } from "react-router-dom";
import { fetchWithCache, invalidateCache, CACHE_KEYS, isCached } from "../../utils/cache";
import { cacheGet, cacheSet } from "../../utils/cacheStorage";
import API_URL from "../../utils/api";
import Spinner from "../../components/Spinner";

import { Play, Activity, Clock, FileText, ChevronRight, Check , CheckCircle, Users, ArrowRightLeft } from "lucide-react";
import { AuthContext } from "../../context/AuthContext";
import { formatJobCode } from "../../utils/serialUtils";

export default function Dashboard() {
  const { user } = useContext(AuthContext);
  const [stats, setStats] = useState({
    ongoingJobs: 0,
    completedJobs: 0,
    activeAnalysts: 0,
    pendingTransfers: 0,
  });
  const [recentActivity, setRecentActivity] = useState([]);
  const [statsLoading, setStatsLoading] = useState(
    () =>
      !isCached(CACHE_KEYS.JOBS) ||
      !isCached(CACHE_KEYS.INSTANCES),
  );

  useEffect(() => {
    const fetchStats = async () => {
      try {
        // Use cache for initial render
        const cachedStats = await cacheGet(CACHE_KEYS.STATS);
        const cachedInstances = await cacheGet(CACHE_KEYS.INSTANCES);
        // Note: sample-transfers aren't globally cached yet, so we'll just skip them in the 0ms render or use 0

        const computeStats = (statsObj, instances, pendingIn, pendingOut) => {
          if (!statsObj) statsObj = { ongoingJobs: 0, completedJobs: 0 };
          if (!Array.isArray(instances)) instances = [];

          const activeAnalysts = new Set(
            instances
              .filter((i) => i.status === "PENDING" && i.assignedTo)
              .map((i) => i.assignedTo._id || i.assignedTo),
          ).size;

          const pendingTransfers = pendingIn + pendingOut;

          setStats({
            ongoingJobs: statsObj.ongoingJobs || 0,
            completedJobs: statsObj.completedJobs || 0,
            activeAnalysts,
            pendingTransfers,
          });

          // Get latest 5 activities in this department
          const sortedInstances = [...instances]
            .filter(
              (i) =>
                i.createdBy?.department === user?.department ||
                i.assignedTo?.department === user?.department,
            )
            .sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt))
            .slice(0, 5);

          setRecentActivity(sortedInstances);
        };

        if (cachedStats && cachedInstances) {
          computeStats(
            cachedStats,
            cachedInstances,
            0,
            0,
          );
        }

        const [
          statsRes,
          instancesRes,
          usersRes,
          inTransfersRes,
          outTransfersRes,
        ] = await Promise.all([
          axios.get(`${API_URL}/api/jobs/stats`),
          axios.get(`${API_URL}/api/tests/instances`),
          axios.get(`${API_URL}/api/users`),
          axios.get(`${API_URL}/api/sample-transfers/incoming`, {
            headers: {
              Authorization: `Bearer ${localStorage.getItem("token")}`,
            },
          }),
          axios.get(`${API_URL}/api/sample-transfers/outgoing`, {
            headers: {
              Authorization: `Bearer ${localStorage.getItem("token")}`,
            },
          }),
        ]);

        cacheSet(CACHE_KEYS.STATS, statsRes.data);
        cacheSet(CACHE_KEYS.INSTANCES, instancesRes.data);

        computeStats(
          statsRes.data,
          instancesRes.data,
          inTransfersRes.data.length,
          outTransfersRes.data.length,
        );
        cacheSet(CACHE_KEYS.USERS, usersRes.data);
      } catch (err) {
        console.error("Error fetching dashboard stats:", err);
      } finally {
        setStatsLoading(false);
      }
    };
    fetchStats();
  }, [user]);

  const StatCard = ({ icon: Icon, title, value, color, subtitle }) => (
    <div
      className="card"
      style={{
        flex: 1,
        minWidth: "220px",
        display: "flex",
        flexDirection: "column",
        gap: "1rem",
        borderTop: `4px solid ${color}`,
      }}
    >
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "flex-start",
        }}
      >
        <div
          style={{
            padding: "0.6rem",
            backgroundColor: `${color}15`,
            color: color,
            borderRadius: "var(--radius-md)",
          }}
        >
          <Icon size={20} />
        </div>
        <div
          style={{
            fontSize: "1.75rem",
            fontWeight: 700,
            color: "var(--color-text-main)",
          }}
        >
          {value}
        </div>
      </div>
      <div>
        <div
          style={{
            fontWeight: 600,
            color: "var(--color-text-main)",
            fontSize: "0.9rem",
          }}
        >
          {title}
        </div>
        <div style={{ fontSize: "0.75rem", color: "var(--color-text-muted)" }}>
          {subtitle}
        </div>
      </div>
    </div>
  );

  return (
    <div>
      <div style={{ marginBottom: "2.5rem" }}>
        <h1 style={{ marginBottom: "0.5rem", letterSpacing: "-0.025em" }}>
          Head Dashboard
        </h1>
      </div>

      <div className="stat-cards">
        <StatCard
          icon={Activity}
          title="Ongoing Jobs"
          value={stats.ongoingJobs}
          color="var(--color-primary)"
          subtitle="Currently in progress"
        />
        <StatCard
          icon={CheckCircle}
          title="Completed Jobs"
          value={stats.completedJobs}
          color="var(--color-success)"
          subtitle="Fully completed"
        />
        <StatCard
          icon={Users}
          title="Active Analysts"
          value={stats.activeAnalysts}
          color="#8B5CF6"
          subtitle="Currently working on jobs"
        />
        <StatCard
          icon={ArrowRightLeft}
          title="Pending Transfers"
          value={stats.pendingTransfers}
          color="#F59E0B"
          subtitle="Awaiting hand-over or receipt"
        />
      </div>

      <div className="card" style={{ padding: 0 }}>
        <div
          style={{
            padding: "1.25rem 1.5rem",
            borderBottom: "1px solid var(--color-border)",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <h3
            style={{
              margin: 0,
              fontSize: "1.1rem",
              display: "flex",
              alignItems: "center",
              gap: "0.5rem",
            }}
          >
            <Activity size={18} /> Recent Activity
          </h3>
        </div>
        <div className="table-scroll">
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead style={{ backgroundColor: "var(--color-surface-hover)" }}>
              <tr>
                <th
                  style={{
                    fontSize: "0.8rem",
                    textTransform: "uppercase",
                    letterSpacing: "0.05em",
                  }}
                >
                  ID / Code
                </th>
                <th
                  style={{
                    fontSize: "0.8rem",
                    textTransform: "uppercase",
                    letterSpacing: "0.05em",
                  }}
                >
                  Client
                </th>
                <th
                  style={{
                    fontSize: "0.8rem",
                    textTransform: "uppercase",
                    letterSpacing: "0.05em",
                  }}
                >
                  Analyst
                </th>
                <th
                  style={{
                    fontSize: "0.8rem",
                    textTransform: "uppercase",
                    letterSpacing: "0.05em",
                  }}
                >
                  Status
                </th>
              </tr>
            </thead>
            <tbody>
              {statsLoading ? (
                <tr>
                  <td colSpan="4">
                    <Spinner message="Fetching activity..." />
                  </td>
                </tr>
              ) : recentActivity.length === 0 ? (
                <tr>
                  <td
                    colSpan="4"
                    style={{
                      textAlign: "center",
                      padding: "2.5rem",
                      color: "var(--color-text-muted)",
                    }}
                  >
                    No recent activity detected.
                  </td>
                </tr>
              ) : (
                recentActivity.map((inst) => (
                  <tr key={inst._id}>
                    <td
                      style={{
                        fontFamily: "var(--font-mono)",
                        fontSize: "0.85rem",
                      }}
                    >
                      {formatJobCode(inst.testCode)}
                    </td>
                    <td style={{ fontWeight: 500 }}>{inst.clientName}</td>
                    <td>
                      {inst.assignedTo?.name || (
                        <span style={{ color: "var(--color-text-muted)" }}>
                          Unassigned
                        </span>
                      )}
                    </td>
                    <td>
                      <span
                        className={`badge ${inst.status === "COMPLETED" ? "badge-success" : "badge-warning"}`}
                      >
                        {inst.status === "COMPLETED"
                          ? "Finished"
                          : "In Progress"}
                      </span>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect, useContext } from "react";
import axios from "axios";
import { useLocation, useNavigate } from "react-router-dom";
import { fetchWithCache, invalidateCache, CACHE_KEYS, isCached } from "../../utils/cache";
import { cacheGet, cacheSet } from "../../utils/cacheStorage";
import API_URL from "../../utils/api";
import Spinner from "../../components/Spinner";

import { 
  Play, Plus, Check, Clock, Edit, FileText, XCircle, Search, LogOut, ChevronDown, 
  ChevronRight, ArrowLeft, Download, Eye, LayoutDashboard, Users, Activity as ActivityIcon, RefreshCw, X, Shield,
  ClipboardCheck, CheckCircle, RotateCcw } from "lucide-react";
import { useSocket } from "../../context/SocketContext";
import { AuthContext } from "../../context/AuthContext";
import { formatJobCode } from "../../utils/serialUtils";

export default function ReviewQueue() {
  const { user } = useContext(AuthContext);
  const [instances, setInstances] = useState([]);
  const [selectedInstance, setSelectedInstance] = useState(null);
  const [reassignNote, setReassignNote] = useState("");
  const [showReassignForm, setShowReassignForm] = useState(null); // instance._id when reassign mode is active
  const [success, setSuccess] = useState("");
  const [reviewLoading, setReviewLoading] = useState(
    () => !isCached(CACHE_KEYS.INSTANCES),
  );
  const [assistants, setAssistants] = useState([]);
  const [submittingReviewId, setSubmittingReviewId] = useState(null);

  // Selective reassignment state: { [parameterId]: { selected: bool, assignedTo: userId } }
  const [paramSelections, setParamSelections] = useState({});

  const fetchReviewItems = async () => {
    try {
      await fetchWithCache(
        `${API_URL}/api/tests/instances`,
        CACHE_KEYS.INSTANCES,
        (data) =>
          setInstances(data.filter((i) => i.status === "PENDING_HEAD_REVIEW")),
      );
    } catch (err) {
      console.error(err);
    } finally {
      setReviewLoading(false);
    }
  };

  useEffect(() => {
    fetchReviewItems();
    // Fetch assistants in this department for the analyst dropdown
    fetchWithCache(`${API_URL}/api/users`, CACHE_KEYS.USERS, (data) =>
      setAssistants(
        data.filter(
          (u) => u.role === "ASSISTANT" && u.department === user?.department,
        ),
      ),
    ).catch(console.error);
  }, []);

  const socket = useSocket();

  useEffect(() => {
    if (!socket) return;
    const refresh = () => {
      invalidateCache(CACHE_KEYS.INSTANCES, CACHE_KEYS.JOBS, CACHE_KEYS.STATS);
      fetchReviewItems();
    };

    socket.on("TEST_SUBMITTED", refresh);
    socket.on("TEST_REVIEWED", refresh);

    return () => {
      socket.off("TEST_SUBMITTED", refresh);
      socket.off("TEST_REVIEWED", refresh);
    };
  }, [socket]);

  const handleApprove = async (id) => {
    setSubmittingReviewId(id);
    try {
      await axios.put(`${API_URL}/api/tests/instances/${id}/review`, {
        action: "APPROVE",
      });
      setSuccess("Approved and Completed. Report Generated.");
      invalidateCache(CACHE_KEYS.INSTANCES, CACHE_KEYS.JOBS, CACHE_KEYS.STATS);
      fetchReviewItems();
      setSelectedInstance(null);
      setTimeout(() => setSuccess(""), 4000);
    } catch (err) {
      console.error(err);
    } finally {
      setSubmittingReviewId(null);
    }
  };

  const enterReassignMode = (inst) => {
    setShowReassignForm(inst._id);
    const selections = {};
    inst.results.forEach((r) => {
      if (r.isPanel && r.panelName) {
        const pKey = `panel-${r.panelName.toLowerCase()}`;
        if (!selections[pKey]) {
          selections[pKey] = {
            selected: false,
            assignedTo:
              r.assignedTo || inst.assignedTo?._id || inst.assignedTo || "",
          };
        }
      } else {
        selections[r.parameterId] = {
          selected: false,
          assignedTo:
            r.assignedTo || inst.assignedTo?._id || inst.assignedTo || "",
        };
      }
    });
    setParamSelections(selections);
    setReassignNote("");
  };

  const exitReassignMode = () => {
    setShowReassignForm(null);
    setParamSelections({});
    setReassignNote("");
  };

  const toggleParamSelection = (parameterId) => {
    setParamSelections((prev) => ({
      ...prev,
      [parameterId]: {
        ...prev[parameterId],
        selected: !prev[parameterId]?.selected,
      },
    }));
  };

  const changeParamAnalyst = (parameterId, analystId) => {
    setParamSelections((prev) => ({
      ...prev,
      [parameterId]: {
        ...prev[parameterId],
        assignedTo: analystId,
      },
    }));
  };

  const handleReassign = async (id) => {
    const inst = instances.find((j) => j._id === id);
    if (!inst) return;

    const selected = [];
    Object.entries(paramSelections).forEach(([key, v]) => {
      if (v.selected) {
        if (key.startsWith("panel-")) {
          const panelName = key.replace("panel-", "").toUpperCase();
          inst.results.forEach((r) => {
            if (r.isPanel && r.panelName === panelName) {
              selected.push({
                parameterId: r.parameterId,
                assignedTo: v.assignedTo,
              });
            }
          });
        } else {
          selected.push({ parameterId: key, assignedTo: v.assignedTo });
        }
      }
    });

    if (selected.length === 0) {
      return alert("Please select at least one parameter to reassign.");
    }

    setSubmittingReviewId(id);
    try {
      await axios.put(`${API_URL}/api/tests/instances/${id}/review`, {
        action: "REASSIGN",
        note: reassignNote,
        selectedParams: selected,
      });
      setSuccess(`Sent ${selected.length} parameter(s) for retest.`);
      exitReassignMode();
      invalidateCache(CACHE_KEYS.INSTANCES, CACHE_KEYS.JOBS, CACHE_KEYS.STATS);
      fetchReviewItems();
      setSelectedInstance(null);
      setTimeout(() => setSuccess(""), 4000);
    } catch (err) {
      console.error(err);
    } finally {
      setSubmittingReviewId(null);
    }
  };

  const selectedCount = Object.values(paramSelections).filter(
    (v) => v.selected,
  ).length;

  return (
    <div>
      <h1
        style={{
          marginBottom: "1.5rem",
          display: "flex",
          alignItems: "center",
          gap: "0.5rem",
        }}
      >
        <ClipboardCheck size={28} style={{ color: "var(--color-primary)" }} />{" "}
        Review Queue
      </h1>

      {success && (
        <div
          style={{
            position: "fixed",
            top: "6rem",
            right: "2rem",
            zIndex: 1000,
            color: "white",
            backgroundColor: "var(--color-success)",
            padding: "1rem 1.5rem",
            borderRadius: "var(--radius-md)",
            boxShadow: "0 4px 12px rgba(0,0,0,0.15)",
            display: "flex",
            alignItems: "center",
            gap: "0.75rem",
            animation: "slideIn 0.3s ease-out",
          }}
        >
          <CheckCircle size={20} />
          <span style={{ fontWeight: 500 }}>{success}</span>
        </div>
      )}

      {reviewLoading && instances.length === 0 ? (
        <div className="card">
          <Spinner message="Loading review queue..." />
        </div>
      ) : instances.length === 0 ? (
        <div
          className="card"
          style={{
            textAlign: "center",
            padding: "3rem",
            color: "var(--color-text-muted)",
          }}
        >
          No submissions awaiting your review.
        </div>
      ) : (
        <div
          style={{ display: "flex", flexDirection: "column", gap: "1.5rem" }}
        >
          {instances.map((inst) => {
            const isReassignMode = showReassignForm === inst._id;

            return (
              <div
                key={inst._id}
                className="card"
                style={{
                  borderLeft: `4px solid ${isReassignMode ? "var(--color-danger)" : "var(--color-warning)"}`,
                  padding: 0,
                  overflow: "hidden",
                  transition: "border-color 0.2s",
                }}
              >
                {/* Header */}
                <div
                  style={{
                    padding: "1.25rem 1.5rem",
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                    borderBottom: "1px solid var(--color-border)",
                    cursor: "pointer",
                    backgroundColor:
                      selectedInstance === inst._id
                        ? "var(--color-surface-hover)"
                        : "transparent",
                  }}
                  onClick={() =>
                    setSelectedInstance(
                      selectedInstance === inst._id ? null : inst._id,
                    )
                  }
                >
                  <div>
                    <div style={{ fontWeight: 600, fontSize: "1.05rem", display: "flex", alignItems: "center", gap: "0.5rem" }}>
                      <span style={{ fontFamily: "monospace", color: "var(--color-primary-dark)" }}>
                        {formatJobCode(inst.testCode)}
                      </span>
                    </div>
                    <div
                      style={{
                        fontSize: "0.85rem",
                        color: "var(--color-text-muted)",
                        marginTop: "0.3rem",
                      }}
                    >
                      Analyst: {inst.assignedTo?.name} · Client: {inst.clientName}
                    </div>
                  </div>
                  <span className="badge badge-warning">Awaiting Review</span>
                </div>

                {/* Expanded detail */}
                {selectedInstance === inst._id && (
                  <div style={{ padding: "1.5rem" }}>
                    {/* Review history */}
                    {inst.reviewHistory && inst.reviewHistory.length > 0 && (
                      <div
                        style={{
                          marginBottom: "1.5rem",
                          padding: "1rem",
                          backgroundColor: "rgba(241, 196, 15, 0.05)",
                          borderRadius: "var(--radius-md)",
                          border: "1px solid var(--color-warning)",
                        }}
                      >
                        <div
                          style={{
                            fontWeight: 600,
                            marginBottom: "0.5rem",
                            fontSize: "0.85rem",
                            color: "var(--color-warning)",
                          }}
                        >
                          Previous Review History
                        </div>
                        {inst.reviewHistory.map((rh, i) => (
                          <div
                            key={i}
                            style={{
                              fontSize: "0.8rem",
                              color: "var(--color-text-muted)",
                              marginBottom: "0.3rem",
                            }}
                          >
                            <strong>{rh.role}</strong> {rh.action}{" "}
                            {rh.note && `("${rh.note}")`}{" "}
                            {new Date(rh.date).toLocaleString()}
                          </div>
                        ))}
                      </div>
                    )}

                    {/* Sample Description (read-only) */}
                    {inst.sampleDescription && (
                      <div style={{
                        marginBottom: '1rem',
                        padding: '0.75rem 1rem',
                        backgroundColor: 'var(--color-surface-hover)',
                        borderRadius: 'var(--radius-md)',
                        border: '1px solid var(--color-border)',
                        fontSize: '0.875rem'
                      }}>
                        <div style={{ fontWeight: 600, marginBottom: '0.35rem', color: 'var(--color-text-muted)', fontSize: '0.78rem', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                          Sample Description
