import React, { useState, useEffect, useContext } from "react";
import axios from "axios";
import { ArrowRightLeft, PackageOpen, AlertCircle, Check, Send, PackageCheck } from "lucide-react";
import API_URL from "../../utils/api";
import Spinner from "../../components/Spinner";
import { formatJobCode } from "../../utils/serialUtils";
import { useSocket } from "../../context/SocketContext";
import { AuthContext } from "../../context/AuthContext";
import { fetchWithCache, invalidateCache, CACHE_KEYS, isCached } from "../../utils/cache";

export default function TransferManagement() {
  const [incomingTransfers, setIncomingTransfers] = useState([]);
  const [outgoingJobs, setOutgoingJobs] = useState([]);
  const [transferListLoading, setTransferListLoading] = useState(
    () => !isCached(CACHE_KEYS.TRANSFERS_IN) || !isCached(CACHE_KEYS.TRANSFERS_OUT)
  );
  const [transferLoading, setTransferLoading] = useState(false);
  const [transferConfirmData, setTransferConfirmData] = useState(null);
  const { user } = useContext(AuthContext);

  const socket = useSocket();

  const fetchTransfers = async () => {
    try {
      const p1 = fetchWithCache(
        `${API_URL}/api/sample-transfers/incoming`,
        CACHE_KEYS.TRANSFERS_IN,
        setIncomingTransfers,
        { Authorization: `Bearer ${localStorage.getItem("token")}` },
      );
      const p2 = fetchWithCache(
        `${API_URL}/api/sample-transfers/outgoing`,
        CACHE_KEYS.TRANSFERS_OUT,
        setOutgoingJobs,
        { Authorization: `Bearer ${localStorage.getItem("token")}` },
      );
      await Promise.all([p1, p2]);
    } catch (err) {
      console.error("Error fetching transfers:", err);
    } finally {
      setTransferListLoading(false);
    }
  };

  useEffect(() => {
    fetchTransfers();
  }, []);

  useEffect(() => {
    if (!socket) return;
    const updateTransfers = () => {
      invalidateCache(CACHE_KEYS.TRANSFERS_IN, CACHE_KEYS.TRANSFERS_OUT);
      fetchTransfers();
    };
    socket.on("TRANSFER_INITIATED", updateTransfers);
    socket.on("TRANSFER_RECEIVED", updateTransfers);
    return () => {
      socket.off("TRANSFER_INITIATED", updateTransfers);
      socket.off("TRANSFER_RECEIVED", updateTransfers);
    };
  }, [socket]);

  const handleSendTransferClick = (jobId) => {
    setTransferConfirmData({
      type: "send",
      id: jobId,
      title: "Hand Over Sample",
      message:
        "You are handing over this sample to the other department. This action will be recorded and cannot be undone.",
    });
  };

  const handleReceiveTransferClick = (transferId) => {
    setTransferConfirmData({
      type: "receive",
      id: transferId,
      title: "Confirm Receipt",
      message:
        "You are confirming receipt of this sample. The job will become available in your dispatcher.",
    });
  };

  const executeTransfer = async () => {
    if (!transferConfirmData || transferLoading) return;
    const { type, id } = transferConfirmData;
    setTransferLoading(true);

    try {
      if (type === "send") {
        await axios.post(
          `${API_URL}/api/sample-transfers`,
          { jobId: id },
          {
            headers: {
              Authorization: `Bearer ${localStorage.getItem("token")}`,
            },
          },
        );
        setSuccess(
          "Sample hand-over recorded! The other department has been notified.",
        );
        setOutgoingJobs((prev) => prev.filter((j) => j._id !== id));
      } else if (type === "receive") {
        await axios.put(
          `${API_URL}/api/sample-transfers/${id}/receive`,
          {},
          {
            headers: {
              Authorization: `Bearer ${localStorage.getItem("token")}`,
            },
          },
        );

        // Immediately remove from UI for snappy experience
        setIncomingTransfers((prev) => prev.filter((t) => t._id !== id));

        setSuccess(
          "Sample receipt confirmed! The job is now available in your dispatcher.",
        );
        invalidateCache(CACHE_KEYS.JOBS);
      }
      setTimeout(() => setSuccess(""), 4000);
      fetchTransfers();
      setTransferConfirmData(null);
    } catch (err) {
      alert(
        err.response?.data?.message ||
        `Error ${type === "send" ? "sending" : "receiving"} transfer`,
      );
    } finally {
      setTransferLoading(false);
    }
  };

  return (
    <>
      {(incomingTransfers.length > 0 || outgoingJobs.length > 0) && (
        <div
          style={{
            marginBottom: "2.5rem",
            paddingBottom: "2rem",
            borderBottom: "2px dashed var(--color-border)",
          }}
        >
          <h1
            style={{
              fontSize: "1.4rem",
              fontWeight: 700,
              marginBottom: "1.5rem",
              display: "flex",
              alignItems: "center",
              gap: "0.5rem",
              color: "var(--color-text-main)",
            }}
          >
            <ArrowRightLeft size={24} /> Sample Transfer Management
          </h1>

          {/* ── Incoming Transfers ── */}
          {transferListLoading &&
            incomingTransfers.length === 0 &&
            outgoingJobs.length === 0 ? (
            <Spinner message="Loading transfers..." />
          ) : (
            incomingTransfers.length > 0 && (
              <div style={{ marginBottom: "1.5rem" }}>
                <h2
                  style={{
                    fontSize: "1.1rem",
                    fontWeight: 600,
                    marginBottom: "0.75rem",
                    display: "flex",
                    alignItems: "center",
                    gap: "0.5rem",
                    color: "var(--color-warning)",
                  }}
                >
                  <PackageCheck size={20} /> Incoming Samples — Action Required
                </h2>
                <div
                  style={{
                    display: "flex",
                    flexDirection: "column",
                    gap: "0.75rem",
                  }}
                >
                  {incomingTransfers.map((transfer) => (
                    <div
                      key={transfer._id}
                      className="card"
                      style={{
                        padding: "1.25rem 1.5rem",
                        border: "2px solid var(--color-warning)",
                        backgroundColor: "rgba(241, 196, 15, 0.05)",
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "center",
                        flexWrap: "wrap",
                        gap: "1rem",
                      }}
                    >
                      <div>
                        <div
                          style={{
                            fontWeight: 700,
                            fontSize: "1rem",
                            marginBottom: "0.3rem",
                          }}
                        >
                          📦 Sample from{" "}
                          {transfer.fromDepartment === "micro"
                            ? "Micro"
                            : "Chemical"}{" "}
                          Department
                        </div>
                        <div
                          style={{
                            fontSize: "0.85rem",
                            color: "var(--color-text-muted)",
                          }}
                        >
                          Sample Serial:{" "}
                          <strong>#{transfer.sampleSerial}</strong>
                          {transfer.jobId?.clientName && ` · ${transfer.jobId.clientName}`}
                        </div>
                        <div
                          style={{
                            fontSize: "0.8rem",
                            color: "var(--color-text-muted)",
                            marginTop: "0.2rem",
                          }}
                        >
                          Sent by: {transfer.sentBy?.name || "Unknown"} ·{" "}
                          {new Date(transfer.sentAt).toLocaleString()}
                        </div>
                      </div>
                      <button
                        onClick={() => handleReceiveTransferClick(transfer._id)}
                        disabled={transferLoading}
                        className="btn btn-primary"
                        style={{
                          padding: "0.6rem 1.2rem",
                          display: "flex",
                          alignItems: "center",
                          gap: "0.4rem",
                        }}
                      >
                        <Check size={16} />{" "}
                        {transferLoading ? "Processing..." : "Confirm Receipt"}
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )
          )}

          {/* ── Outgoing Transfers (Hand Over) ── */}
          {outgoingJobs.length > 0 && (
            <div style={{ marginBottom: "1.5rem" }}>
              <h2
                style={{
                  fontSize: "1.1rem",
                  fontWeight: 600,
                  marginBottom: "0.75rem",
                  display: "flex",
                  alignItems: "center",
                  gap: "0.5rem",
                  color: "var(--color-primary)",
                }}
              >
                <Send size={20} /> Samples Ready for Hand-Over
              </h2>
              <div
                style={{
                  display: "flex",
                  flexDirection: "column",
                  gap: "0.75rem",
                }}
              >
                {outgoingJobs.map((job) => {
                  const secondDept =
                    user?.department?.toLowerCase() === "micro"
                      ? "Chemical"
                      : "Micro";
                  return (
                    <div
                      key={job._id}
                      className="card"
                      style={{
                        padding: "1.25rem 1.5rem",
                        border: "2px solid var(--color-primary)",
                        backgroundColor: "rgba(52, 152, 219, 0.05)",
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "center",
                        flexWrap: "wrap",
                        gap: "1rem",
                      }}
                    >
                      <div>
                        <div
                          style={{
                            fontWeight: 700,
                            fontSize: "1rem",
                            marginBottom: "0.3rem",
                          }}
                        >
                          🔄 Hand Over to {secondDept} Department
                        </div>
                        <div
                          style={{
                            fontSize: "0.85rem",
                            color: "var(--color-text-muted)",
                          }}
                        >
                          Sample Serial: <strong>#{job.sampleSerial}</strong>{" "}
                          {job.clientName ? `— ${job.clientName}` : ""}
                        </div>
                        <div
                          style={{
                            fontSize: "0.8rem",
                            color: "var(--color-text-muted)",
                            marginTop: "0.2rem",
                          }}
                        >
                          Please hand over the sample to the {secondDept}{" "}
                          department once you have taken your required portion.
                        </div>
                      </div>
                      <button
                        onClick={() => handleSendTransferClick(job._id)}
                        disabled={transferLoading}
                        className="btn"
                        style={{
                          padding: "0.6rem 1.2rem",
                          display: "flex",
                          alignItems: "center",
                          gap: "0.4rem",
                          backgroundColor: "var(--color-primary)",
                          color: "white",
                        }}
                      >
                        <ArrowRightLeft size={16} />{" "}
                        {transferLoading ? "Processing..." : "Hand Over Sample"}
                      </button>
                    </div>
                  );
                })}
              </div>
            </div>
          )}
        </div>
      )}
      {/* ── End Sample Transfers Section ── */}
      {/* ── CUSTOM CONFIRMATION MODAL ── */}
      {transferConfirmData && (
        <div className="modal-overlay">
          <div className="modal-content" style={{ maxWidth: "400px", textAlign: "center" }}>
            <h3 style={{ margin: "0 0 1rem 0", color: "var(--color-primary)", display: "flex", alignItems: "center", justifyContent: "center", gap: "0.5rem" }}>
              <AlertCircle size={24} /> {transferConfirmData.title}
            </h3>
            <p style={{ marginBottom: "2rem" }}>{transferConfirmData.message}</p>
            <div className="form-actions" style={{ display: "flex", gap: "1rem", justifyContent: "center" }}>
              <button className="btn btn-secondary" onClick={() => setTransferConfirmData(null)}>
                Cancel
              </button>
              <button className="btn btn-primary" onClick={() => executeTransfer()} disabled={transferLoading}>
                {transferLoading ? "Processing..." : "Confirm"}
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

import React, { useState, useContext } from 'react';
import { AuthContext } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';
import { Lock, Mail, ArrowRight, Activity, Eye, EyeOff, KeyRound, ArrowLeft } from 'lucide-react';
import axios from 'axios';
import logo from '../assets/Acropolis20Logo.png';
import API_URL from '../utils/api';

export default function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [requiresChange, setRequiresChange] = useState(false);
  const [error, setError] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showNewPassword, setShowNewPassword] = useState(false);
  const { login, setUser } = useContext(AuthContext);
  const navigate = useNavigate();

  // OTP state
  const [otpMode, setOtpMode] = useState(null); // null | 'email' | 'verify'
  const [otpEmail, setOtpEmail] = useState('');
  const [otpCode, setOtpCode] = useState('');
  const [otpLoading, setOtpLoading] = useState(false);
  const [otpMessage, setOtpMessage] = useState('');
  const [otpCountdown, setOtpCountdown] = useState(0);

  const handleLoginSubmit = async (e) => {
    e.preventDefault();
    setError('');
    try {
      const u = await login(email, password);
      if (u.requiresPasswordChange) {
        setRequiresChange(true);
      } else {
        redirectRole(u.role);
      }
    } catch (err) {
      if (err.response) {
        setError(err.response.data?.message || 'Invalid credentials');
      } else {
        setError('Network Error: Cannot connect to server');
      }
    }
  };

  const handleChangePassword = async (e) => {
    e.preventDefault();
    try {
      await axios.put(`${API_URL}/api/auth/change-password`, { newPassword });
      const updatedUser = { ...JSON.parse(localStorage.getItem('user')), requiresPasswordChange: false };
      localStorage.setItem('user', JSON.stringify(updatedUser));
      redirectRole(updatedUser.role);
    } catch (err) {
      setError('Failed to update password');
    }
  };

  const redirectRole = (role) => {
    if (role === 'ADMIN') navigate('/admin');
    else if (role === 'ADMIN_OFFICER') navigate('/admin-officer');
    else if (role === 'HEAD') navigate('/head');
    else if (role === 'ASSISTANT') navigate('/assistant');
  };

  // ── OTP Handlers ──

  const startCountdown = () => {
    setOtpCountdown(300); // 5 minutes in seconds
    const interval = setInterval(() => {
      setOtpCountdown(prev => {
        if (prev <= 1) { clearInterval(interval); return 0; }
        return prev - 1;
      });
    }, 1000);
  };

  const formatCountdown = (seconds) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  const handleRequestOtp = async (e) => {
    e.preventDefault();
    setError('');
    setOtpMessage('');
    setOtpLoading(true);
    try {
      const res = await axios.post(`${API_URL}/api/auth/request-otp`, { email: otpEmail });
      setOtpMessage(res.data.message);
      setOtpMode('verify');
      startCountdown();
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to send OTP.');
    } finally {
      setOtpLoading(false);
    }
  };

  const handleVerifyOtp = async (e) => {
    e.preventDefault();
    setError('');
    setOtpLoading(true);
    try {
      const res = await axios.post(`${API_URL}/api/auth/verify-otp`, { email: otpEmail, otp: otpCode });
      // Store user + token and redirect (direct login)
      const userData = res.data;
      localStorage.setItem('token', userData.token);
      localStorage.setItem('user', JSON.stringify(userData));
      axios.defaults.headers.common['Authorization'] = `Bearer ${userData.token}`;
      setUser(userData);
      redirectRole(userData.role);
    } catch (err) {
      setError(err.response?.data?.message || 'OTP verification failed.');
    } finally {
      setOtpLoading(false);
    }
  };

  const exitOtpMode = () => {
    setOtpMode(null);
    setOtpEmail('');
    setOtpCode('');
    setOtpMessage('');
    setOtpCountdown(0);
    setError('');
  };

  return (
    <div className="flex-center mesh-gradient" style={{ height: '100dvh', width: '100vw', overflow: 'hidden', padding: '0', boxSizing: 'border-box' }}>
      {/* Decorative Blur Orbs */}
      <div style={{ position: 'absolute', top: '15%', left: '10%', width: '350px', height: '350px', background: 'radial-gradient(circle, rgba(64,158,255,0.1) 0%, transparent 70%)', filter: 'blur(60px)', zIndex: 1 }}></div>
      <div style={{ position: 'absolute', bottom: '15%', right: '10%', width: '450px', height: '450px', background: 'radial-gradient(circle, rgba(16,185,129,0.05) 0%, transparent 70%)', filter: 'blur(70px)', zIndex: 1 }}></div>

      <div className="premium-glass fade-in-up login-card" style={{ width: '100%', maxWidth: '480px', padding: '3rem 3.5rem', borderRadius: '28px', zIndex: 10, backgroundColor: 'rgba(255, 255, 255, 0.9)', boxShadow: '0 20px 40px rgba(0,0,0,0.2)' }}>
        <div style={{ textAlign: 'center', marginBottom: '1.5rem' }}>
          <img
            src={logo}
            alt="Acropolis Logo"
            className="login-logo"
            style={{ width: '260px', marginBottom: '0.5rem' }}
          />
        </div>

        {error && (
          <div style={{ backgroundColor: 'var(--color-danger-light)', border: '1px solid var(--color-danger)', color: 'var(--color-danger)', padding: '1rem', borderRadius: '14px', marginBottom: '1.5rem', fontSize: '0.85rem', display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <Activity size={16} /> {error}
          </div>
        )}

        {otpMessage && !error && (
          <div style={{ backgroundColor: '#dcfce7', border: '1px solid #86efac', color: '#166534', padding: '1rem', borderRadius: '14px', marginBottom: '1.5rem', fontSize: '0.85rem', display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <Mail size={16} /> {otpMessage}
          </div>
        )}

        {/* ── OTP Flow: Enter Email ── */}
        {otpMode === 'email' && (
          <form onSubmit={handleRequestOtp} style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '0.5rem' }}>
              <button type="button" onClick={exitOtpMode} style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--color-text-muted)', padding: '0.25rem', display: 'flex' }}>
                <ArrowLeft size={20} />
              </button>
              <div>
                <h3 style={{ margin: 0, fontSize: '1.1rem', color: 'var(--color-text-main)' }}>Login via OTP</h3>
                <p style={{ margin: '0.25rem 0 0', fontSize: '0.8rem', color: 'var(--color-text-muted)' }}>Enter your registered email to receive a one-time code.</p>
              </div>
            </div>
            <div>
              <label style={{ display: 'block', marginBottom: '0.6rem', fontWeight: 500, color: 'var(--color-text-main)', fontSize: '0.85rem' }}>Email Address</label>
              <div style={{ position: 'relative' }}>
                <Mail size={18} style={{ position: 'absolute', left: '1.25rem', top: '50%', transform: 'translateY(-50%)', color: 'var(--color-text-muted)' }} />
                <input
                  type="email"
                  placeholder="name@acropolis.com"
                  style={{ paddingLeft: '3rem', background: '#FFFFFF', border: '1px solid var(--color-border)', color: 'var(--color-text-main)', height: '54px', borderRadius: '14px' }}
                  value={otpEmail}
                  onChange={e => setOtpEmail(e.target.value)}
                  required
                  autoFocus
                />
              </div>
            </div>
            <button type="submit" className="btn btn-primary" disabled={otpLoading} style={{ width: '100%', height: '54px', borderRadius: '14px', fontWeight: 600 }}>
              {otpLoading ? 'Sending OTP...' : 'Send OTP'} <Mail size={18} />
            </button>
          </form>
        )}

        {/* ── OTP Flow: Verify Code ── */}
        {otpMode === 'verify' && (
          <form onSubmit={handleVerifyOtp} style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '0.5rem' }}>
              <button type="button" onClick={() => { setOtpMode('email'); setOtpCode(''); setError(''); }} style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--color-text-muted)', padding: '0.25rem', display: 'flex' }}>
                <ArrowLeft size={20} />
              </button>
              <div>
                <h3 style={{ margin: 0, fontSize: '1.1rem', color: 'var(--color-text-main)' }}>Enter OTP</h3>
                <p style={{ margin: '0.25rem 0 0', fontSize: '0.8rem', color: 'var(--color-text-muted)' }}>
                  Check <strong>{otpEmail}</strong> for your 6-digit code.
                </p>
              </div>
            </div>

            <div>
              <label style={{ display: 'block', marginBottom: '0.6rem', fontWeight: 500, color: 'var(--color-text-main)', fontSize: '0.85rem' }}>One-Time Password</label>
              <div style={{ position: 'relative' }}>
                <KeyRound size={18} style={{ position: 'absolute', left: '1.25rem', top: '50%', transform: 'translateY(-50%)', color: 'var(--color-text-muted)' }} />
                <input
                  type="text"
                  inputMode="numeric"
                  maxLength={6}
                  placeholder="• • • • • •"
                  style={{
                    paddingLeft: '3rem', background: '#FFFFFF', border: '1px solid var(--color-border)',
                    color: 'var(--color-text-main)', height: '54px', borderRadius: '14px',
                    fontSize: '1.5rem', letterSpacing: '0.5rem', fontWeight: 700, textAlign: 'center', fontFamily: "'Courier New', monospace"
                  }}
                  value={otpCode}
                  onChange={e => setOtpCode(e.target.value.replace(/\D/g, '').slice(0, 6))}
                  required
                  autoFocus
                />
              </div>
            </div>

            {otpCountdown > 0 && (
              <div style={{ textAlign: 'center', fontSize: '0.85rem', color: otpCountdown < 60 ? 'var(--color-danger)' : 'var(--color-text-muted)', fontWeight: 600 }}>
                ⏱ Code expires in {formatCountdown(otpCountdown)}
              </div>
            )}
            {otpCountdown === 0 && otpMode === 'verify' && (
              <div style={{ textAlign: 'center', fontSize: '0.85rem', color: 'var(--color-danger)', fontWeight: 600 }}>
                Code expired.{' '}
                <button type="button" onClick={() => { setOtpMode('email'); setOtpCode(''); setError(''); }} style={{ background: 'none', border: 'none', color: 'var(--color-primary)', cursor: 'pointer', fontWeight: 600, textDecoration: 'underline', fontSize: '0.85rem' }}>
                  Resend OTP
                </button>
              </div>
            )}

            <button type="submit" className="btn btn-primary" disabled={otpLoading || otpCode.length < 6} style={{ width: '100%', height: '54px', borderRadius: '14px', fontWeight: 600, opacity: otpCode.length < 6 ? 0.5 : 1 }}>
              {otpLoading ? 'Verifying...' : 'Verify & Login'} <ArrowRight size={18} />
            </button>
          </form>
        )}

        {/* ── Password Change (first-time login) ── */}
        {!otpMode && requiresChange && (
          <form onSubmit={handleChangePassword} style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
            <div>
              <label style={{ display: 'block', marginBottom: '0.6rem', fontWeight: 500, color: 'var(--color-text-main)', fontSize: '0.85rem' }}>New Password</label>
              <div style={{ position: 'relative' }}>
                <Lock size={18} style={{ position: 'absolute', left: '1.25rem', top: '50%', transform: 'translateY(-50%)', color: 'var(--color-text-muted)' }} />
                <input
                  type={showNewPassword ? 'text' : 'password'}
                  placeholder="Enter new secure password"
                  style={{ paddingLeft: '3rem', paddingRight: '3rem', background: '#FFFFFF', border: '1px solid var(--color-border)', color: 'var(--color-text-main)', height: '54px', borderRadius: '14px' }}
                  value={newPassword}
                  onChange={(e) => setNewPassword(e.target.value)}
                  required
                />
                <button
                  type="button"
                  onClick={() => setShowNewPassword(!showNewPassword)}
                  style={{ position: 'absolute', right: '1rem', top: '50%', transform: 'translateY(-50%)', background: 'none', border: 'none', color: 'var(--color-text-muted)', cursor: 'pointer', padding: '0.25rem', display: 'flex', alignItems: 'center' }}
                >
                  {showNewPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>
            <button type="submit" className="btn btn-primary" style={{ width: '100%', height: '54px', borderRadius: '14px', fontWeight: 600 }}>
              Update Password <ArrowRight size={18} />
            </button>
          </form>
        )}

        {/* ── Normal Login ── */}
        {!otpMode && !requiresChange && (
          <form onSubmit={handleLoginSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
            <div>
              <label style={{ display: 'block', marginBottom: '0.6rem', fontWeight: 500, color: 'var(--color-text-main)', fontSize: '0.85rem' }}>Email Address</label>
              <div style={{ position: 'relative' }}>
                <Mail size={18} style={{ position: 'absolute', left: '1.25rem', top: '50%', transform: 'translateY(-50%)', color: 'var(--color-text-muted)' }} />
                <input
                  type="email"
                  placeholder="name@acropolis.com"
                  style={{ paddingLeft: '3rem', background: '#FFFFFF', border: '1px solid var(--color-border)', color: 'var(--color-text-main)', height: '48px', borderRadius: '14px' }}
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                />
              </div>
            </div>

            <div>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.6rem' }}>
                <label style={{ fontWeight: 500, color: 'var(--color-text-main)', fontSize: '0.85rem' }}>Password</label>
                <button type="button" onClick={() => { setOtpMode('email'); setError(''); }} style={{ background: 'none', border: 'none', color: 'var(--color-primary)', fontSize: '0.8rem', cursor: 'pointer', fontWeight: 500 }}>Login via OTP</button>
              </div>
              <div style={{ position: 'relative' }}>
                <Lock size={18} style={{ position: 'absolute', left: '1.25rem', top: '50%', transform: 'translateY(-50%)', color: 'var(--color-text-muted)' }} />
                <input
                  type={showPassword ? 'text' : 'password'}
                  placeholder="••••••••"
                  style={{ paddingLeft: '3rem', paddingRight: '3rem', background: '#FFFFFF', border: '1px solid var(--color-border)', color: 'var(--color-text-main)', height: '48px', borderRadius: '14px' }}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  style={{ position: 'absolute', right: '1rem', top: '50%', transform: 'translateY(-50%)', background: 'none', border: 'none', color: 'var(--color-text-muted)', cursor: 'pointer', padding: '0.25rem', display: 'flex', alignItems: 'center' }}
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>

            <button type="submit" className="btn btn-primary" style={{ width: '100%', height: '48px', borderRadius: '14px', fontWeight: 600, marginTop: '0.5rem' }}>
              Login <ArrowRight size={18} />
            </button>
          </form>
        )}
      </div>
    </div>
  );
}

import React, { useState, useEffect, useContext } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { Bell, Check, Info, AlertTriangle, CheckCircle, Clock, Circle, X, ArrowLeft } from 'lucide-react';
import { AuthContext } from '../context/AuthContext';
import Spinner from '../components/Spinner';
import { useSocket } from '../context/SocketContext';
import API_URL from '../utils/api';

export default function NotificationsPage() {
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all'); // 'all' | 'unread' | 'read'
  const navigate = useNavigate();
  const { user } = useContext(AuthContext);

  const fetchNotifications = async () => {
    try {
      const res = await axios.get(`${API_URL}/api/notifications`, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
      });
      setNotifications(Array.isArray(res.data) ? res.data : []);
    } catch (err) {
      console.error('Error fetching notifications:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchNotifications(); }, []);

  const socket = useSocket();

  useEffect(() => {
    if (!socket || !user) return;

    const handleNewNotification = (payload) => {
      if (payload.recipientId === user._id) {
        fetchNotifications();
      }
    };

    socket.on('NEW_NOTIFICATION', handleNewNotification);

    return () => {
      socket.off('NEW_NOTIFICATION', handleNewNotification);
    };
  }, [socket, user]);

  const handleMarkAsRead = async (id, e) => {
    if (e) e.stopPropagation();
    try {
      await axios.put(`${API_URL}/api/notifications/${id}/read`, {}, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
      });
      fetchNotifications();
    } catch (err) {
      console.error('Error marking as read:', err);
    }
  };

  const handleDeleteNotification = async (id, e) => {
    if (e) e.stopPropagation();
    try {
      await axios.delete(`${API_URL}/api/notifications/${id}`, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
      });
      fetchNotifications();
    } catch (err) {
      console.error('Error deleting notification:', err);
    }
  };

  const handleMarkAllAsRead = async () => {
    try {
      await axios.put(`${API_URL}/api/notifications/read-all`, {}, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
      });
      fetchNotifications();
    } catch (err) {
      console.error('Error marking all as read:', err);
    }
  };

  const handleNotificationClick = (notification) => {
    if (!notification.read) {
      handleMarkAsRead(notification._id);
    }
    if (notification.link) {
      let targetLink = notification.link;
      if (user && !targetLink.startsWith(`/${user.role.toLowerCase().replace('_', '-')}`)) {
        const prefix = `/${user.role.toLowerCase().replace('_', '-')}`;
        if (targetLink.startsWith('/review') || targetLink.startsWith('/audit') || targetLink.startsWith('/dispatcher')) {
          targetLink = `${prefix}${targetLink}`;
        }
      }
      navigate(targetLink);
    }
  };

  const getIcon = (type) => {
    switch (type) {
      case 'ACTION_REQUIRED': return <AlertTriangle size={20} color="var(--color-warning)" />;
      case 'SUCCESS': return <CheckCircle size={20} color="var(--color-success)" />;
      case 'WARNING': return <AlertTriangle size={20} color="var(--color-danger)" />;
      default: return <Info size={20} color="var(--color-primary)" />;
    }
  };

  const getTypeBadge = (type) => {
    const styles = {
      'ACTION_REQUIRED': { bg: 'rgba(241, 196, 15, 0.12)', color: '#d35400', label: 'Action Required' },
      'SUCCESS': { bg: 'rgba(46, 204, 113, 0.12)', color: 'var(--color-success)', label: 'Success' },
      'WARNING': { bg: 'rgba(231, 76, 60, 0.12)', color: 'var(--color-danger)', label: 'Warning' },
      'INFO': { bg: 'rgba(52, 152, 219, 0.12)', color: 'var(--color-primary)', label: 'Info' }
    };
    const s = styles[type] || styles['INFO'];
    return (
      <span style={{
        fontSize: '0.7rem', fontWeight: 600, padding: '0.15rem 0.5rem',
        borderRadius: '9999px', backgroundColor: s.bg, color: s.color
      }}>
        {s.label}
      </span>
    );
  };

  const filtered = notifications.filter(n => {
    if (filter === 'unread') return !n.read;
    if (filter === 'read') return n.read;
    return true;
  });

  const unreadCount = notifications.filter(n => !n.read).length;

  const filterBtnStyle = (active) => ({
    padding: '0.4rem 1rem',
    fontSize: '0.85rem',
    fontWeight: 500,
    borderRadius: 'var(--radius-md)',
    border: 'none',
    cursor: 'pointer',
    backgroundColor: active ? 'var(--color-primary)' : 'var(--color-surface-hover)',
    color: active ? 'white' : 'var(--color-text-muted)',
    transition: 'all 0.2s'
  });

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto' }}>
      {/* Back button */}
      <button
        onClick={() => navigate(-1)}
        style={{
          display: 'flex', alignItems: 'center', gap: '0.5rem',
          background: 'none', border: 'none', color: 'var(--color-primary)',
          cursor: 'pointer', fontSize: '0.9rem', fontWeight: 500,
          padding: '0.5rem 0', marginBottom: '1rem'
        }}
      >
        <ArrowLeft size={18} /> Back
      </button>

      {/* Header */}
      <div className="flex-row-responsive" style={{ justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
          <Bell size={28} style={{ color: 'var(--color-primary)' }} />
          <h1 style={{ margin: 0 }}>Notifications</h1>
          {unreadCount > 0 && (
            <span style={{
              backgroundColor: 'var(--color-danger)', color: 'white',
              fontSize: '0.75rem', fontWeight: 700, padding: '0.15rem 0.55rem',
              borderRadius: '9999px'
            }}>
              {unreadCount} unread
            </span>
          )}
        </div>
        {unreadCount > 0 && (
          <button
            onClick={handleMarkAllAsRead}
            className="btn"
            style={{
              padding: '0.4rem 1rem', fontSize: '0.85rem',
              display: 'flex', alignItems: 'center', gap: '0.3rem',
              backgroundColor: 'transparent', border: '1px solid var(--color-border)',
              color: 'var(--color-primary)', cursor: 'pointer', borderRadius: 'var(--radius-md)'
            }}
          >
            <Check size={16} /> Mark all read
          </button>
        )}
      </div>

      {/* Filter tabs */}
      <div style={{ display: 'flex', gap: '0.5rem', marginBottom: '1.5rem' }}>
        <button style={filterBtnStyle(filter === 'all')} onClick={() => setFilter('all')}>
          All ({notifications.length})
        </button>
        <button style={filterBtnStyle(filter === 'unread')} onClick={() => setFilter('unread')}>
          Unread ({unreadCount})
        </button>
        <button style={filterBtnStyle(filter === 'read')} onClick={() => setFilter('read')}>
          Read ({notifications.length - unreadCount})
        </button>
      </div>

      {/* Notifications list */}
      {loading ? (
        <Spinner message="Loading notifications..." />
      ) : filtered.length === 0 ? (
        <div className="card" style={{ textAlign: 'center', padding: '3rem', color: 'var(--color-text-muted)' }}>
          <Bell size={40} style={{ marginBottom: '1rem', opacity: 0.3 }} />
          <p style={{ fontSize: '1.1rem', fontWeight: 500, margin: '0 0 0.3rem 0' }}>
            {filter === 'unread' ? 'No unread notifications' : filter === 'read' ? 'No read notifications' : 'No notifications yet'}
          </p>
          <p style={{ fontSize: '0.85rem', margin: 0 }}>
            {filter === 'all' ? "You're all caught up!" : 'Try switching filters.'}
          </p>
        </div>
      ) : (
        <div className="card" style={{ padding: 0, overflow: 'hidden' }}>
          {filtered.map((notif, idx) => (
            <div
              key={notif._id}
              onClick={() => handleNotificationClick(notif)}
              style={{
                padding: '1rem 1.25rem',
                borderBottom: idx < filtered.length - 1 ? '1px solid var(--color-border)' : 'none',
                backgroundColor: notif.read ? 'transparent' : 'rgba(var(--color-primary-rgb), 0.04)',
                cursor: notif.link ? 'pointer' : 'default',
                display: 'flex',
                gap: '1rem',
                alignItems: 'flex-start',
                transition: 'background-color 0.15s',
                position: 'relative'
              }}
              onMouseEnter={(e) => e.currentTarget.style.backgroundColor = 'var(--color-surface-hover)'}
              onMouseLeave={(e) => e.currentTarget.style.backgroundColor = notif.read ? 'transparent' : 'rgba(var(--color-primary-rgb), 0.04)'}
            >
              {/* Unread indicator bar */}
              {!notif.read && (
                <div style={{ position: 'absolute', left: 0, top: 0, bottom: 0, width: '4px', backgroundColor: 'var(--color-primary)', borderRadius: '0 2px 2px 0' }} />
              )}

              {/* Icon */}
              <div style={{ marginTop: '0.15rem', flexShrink: 0 }}>
                {getIcon(notif.type)}
              </div>

              {/* Content */}
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: '0.75rem', marginBottom: '0.3rem' }}>
                  <h4 style={{ margin: 0, fontSize: '0.95rem', fontWeight: notif.read ? 500 : 700, color: 'var(--color-text-main)' }}>
                    {notif.title}
                  </h4>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', flexShrink: 0 }}>
                    {getTypeBadge(notif.type)}
                  </div>
                </div>
                <p style={{ margin: '0 0 0.4rem 0', fontSize: '0.85rem', color: 'var(--color-text-muted)', lineHeight: 1.5 }}>
                  {notif.message}
                </p>
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.75rem', color: 'var(--color-text-muted)' }}>
                  <Clock size={12} />
                  <span>{new Date(notif.createdAt).toLocaleString()}</span>
                </div>
              </div>

              {/* Actions */}
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.4rem', flexShrink: 0 }}>
                {!notif.read && (
                  <button
                    onClick={(e) => handleMarkAsRead(notif._id, e)}
                    style={{ background: 'none', border: 'none', color: 'var(--color-primary)', cursor: 'pointer', padding: '0.25rem' }}
                    title="Mark as read"
                  >
                    <Circle size={14} fill="var(--color-primary)" />
                  </button>
                )}
                <button
                  onClick={(e) => handleDeleteNotification(notif._id, e)}
                  style={{ background: 'none', border: 'none', color: 'var(--color-text-muted)', cursor: 'pointer', padding: '0.25rem' }}
                  title="Remove"
                  onMouseEnter={(e) => e.currentTarget.style.color = 'var(--color-danger)'}
                  onMouseLeave={(e) => e.currentTarget.style.color = 'var(--color-text-muted)'}
                >
                  <X size={14} />
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Footer count */}
      {!loading && filtered.length > 0 && (
        <div style={{ textAlign: 'center', padding: '1rem', fontSize: '0.8rem', color: 'var(--color-text-muted)' }}>
          Showing {filtered.length} of {notifications.length} notification{notifications.length !== 1 ? 's' : ''}
        </div>
      )}
    </div>
  );
}

