            <div
              style={{
                display: "flex",
                gap: "1rem",
                justifyContent: "flex-end",
              }}
            >
              <button
                className="btn"
                onClick={() =>
                  setStatusModal({
                    show: false,
                    type: "",
                    title: "",
                    message: "",
                  })
                }
                style={{
                  border: `1px solid ${statusModal.type === "error" ? "var(--color-danger)" : "var(--color-success)"}`,
                  color:
                    statusModal.type === "error"
                      ? "var(--color-danger)"
                      : "var(--color-success)",
                  padding: "0.6rem 2rem",
                  backgroundColor: "transparent",
                }}
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

